// Read-only pages derive from confirmed records and existing explicit dialogue receipts.
var notebookPage=0,notebookTab='pending',notebookReturn=null,notebookRows=null,notebookGeneration=0;
const notebookDialog=document.createElement('dialog');notebookDialog.id='manager-notebook';notebookDialog.setAttribute('aria-labelledby','notebook-title');document.body.append(notebookDialog);
function notebookScenes(){if(typeof ClubStory.scenes==='function')return ClubStory.scenes(season).sort((a,b)=>b.year-a.year||b.round-a.round||a.id.localeCompare(b.id));const seen=new Set(),out=[];for(let year=1;year<=season.year;year++){for(const e of ClubStory.events(season,year)){const d=ClubStory.scene(season,e.id);if(!d||seen.has(d.id))continue;seen.add(d.id);out.push(d);}}return out.sort((a,b)=>b.year-a.year||b.round-a.round||a.id.localeCompare(b.id));}
function prepareManagerNotebook(){
 const generation=++notebookGeneration;notebookRows=null;
 notebookDialog.innerHTML='<header><div><small>감독의 수첩</small><h2 id="notebook-title" tabindex="-1">함께 남긴 페이지</h2></div><button type="button" data-notebook-close aria-label="감독의 수첩 닫기">닫기</button></header><div class="notebook-cards notebook-loading"><p class="notebook-empty" role="status">지난 경기와 남긴 대답을 정리하고 있습니다…</p></div>';
 $('notebook-title').focus({preventScroll:true});
 requestAnimationFrame(()=>requestAnimationFrame(()=>{if(!notebookDialog.open||generation!==notebookGeneration)return;try{notebookRows=notebookScenes();renderManagerNotebook();$('notebook-title').focus({preventScroll:true});}catch(error){notebookDialog.innerHTML='<header><h2 id="notebook-title" tabindex="-1">수첩을 열지 못했습니다</h2><button type="button" data-notebook-close>닫기</button></header><div class="notebook-cards notebook-loading"><div class="notebook-empty" role="status"><p>기록을 정리하는 동안 문제가 생겼습니다.</p><button type="button" data-notebook-retry>다시 정리하기</button></div></div>';$('notebook-title').focus({preventScroll:true});}}));
}
function openManagerNotebook(trigger=document.activeElement){pauseForPlanning();notebookReturn=trigger;notebookPage=0;notebookTab='pending';notebookDialog.showModal();prepareManagerNotebook();}
function renderManagerNotebook(){
 const chapter=StoryNotebook.chapter(season),all=notebookRows||notebookScenes(),list=all.filter(d=>notebookTab==='complete'?d.step===2:d.step<2),max=Math.max(0,Math.ceil(list.length/2)-1);notebookPage=Math.max(0,Math.min(max,notebookPage));
 const cards=list.slice(notebookPage*2,notebookPage*2+2),esc=escapeText;
 notebookDialog.innerHTML='<header><div><small>'+chapter.attempt+'번째 삶 · '+chapter.division+'부 · 감독의 수첩</small><h2 id="notebook-title" tabindex="-1">'+esc(chapter.title)+'</h2></div><button type="button" data-notebook-close aria-label="감독의 수첩 닫기">닫기</button></header><nav class="notebook-tabs" aria-label="수첩 기록 종류"><button type="button" data-notebook-tab="pending" aria-pressed="'+(notebookTab==='pending')+'">도착한 이야기 '+all.filter(d=>d.step<2).length+'</button><button type="button" data-notebook-tab="complete" aria-pressed="'+(notebookTab==='complete')+'">남긴 대답 '+all.filter(d=>d.step===2).length+'</button></nav><div class="notebook-cards">'+(cards.length?cards.map(d=>'<article class="notebook-card">'+ClubArt.memory(storyIllustration(d)||'locker')+'<div><small>'+d.year+'시즌 · '+d.round+'경기 뒤</small><h3>'+esc(d.title)+'</h3><p>'+esc(d.step===2?d.finalLabel:d.step===1?'첫 대답이 기록됐습니다. 대화를 이어갈 수 있습니다.':d.scene.split('\n\n')[0].split('\n')[0])+'</p><button type="button" data-notebook-event="'+d.id+'">'+(d.step===2?'내 대답 다시 읽기':d.readOnly?'지난 장면 읽기':d.step===1?'대화 이어가기':'이야기 만나기')+'</button></div></article>').join(''):'<p class="notebook-empty">'+(notebookTab==='pending'?'지금 도착한 수첩 이야기를 모두 읽었습니다. 확정한 경기와 남긴 대답이 다음 페이지를 엽니다.':'아직 남긴 대답이 없습니다. 도착한 이야기를 읽고 직접 답하면 이곳에 남습니다.')+'</p>')+'</div><footer><button type="button" data-notebook-page="-1" '+(notebookPage===0?'disabled':'')+'>이전</button><span>'+(notebookPage+1)+' / '+(max+1)+'</span><button type="button" data-notebook-page="1" '+(notebookPage>=max?'disabled':'')+'>다음</button></footer>';
}
notebookDialog.onclick=event=>{const close=event.target.closest('[data-notebook-close]'),tab=event.target.closest('[data-notebook-tab]'),page=event.target.closest('[data-notebook-page]'),scene=event.target.closest('[data-notebook-event]');if(close)return notebookDialog.close();if(event.target.closest('[data-notebook-retry]'))return prepareManagerNotebook();if(tab){notebookTab=tab.dataset.notebookTab;notebookPage=0;renderManagerNotebook();notebookDialog.querySelector('[data-notebook-tab="'+notebookTab+'"]').focus({preventScroll:true});}else if(page&&!page.disabled){notebookPage+=Number(page.dataset.notebookPage);renderManagerNotebook();$('notebook-title').focus({preventScroll:true});}else if(scene){notebookDialog.close();openClubStory(scene.dataset.notebookEvent,notebookReturn);}};
notebookDialog.addEventListener('close',()=>{notebookRows=null;notebookGeneration++;if(notebookReturn?.isConnected&&!notebookReturn.closest('dialog'))notebookReturn.focus({preventScroll:true});});
